def emit():
 out=[]
 for o in a:
  m=model(o['modelId'][4:]);cap=caps[o['modelId']];p=next(x for x in m['parts'] if x['id']==o['componentId']);cp=next(x for x in cap['components'] if x['id']==o['componentId']);g=next(x for x in m['geosets'] if x['geoset1']==p['geoset1']);textures=list(dict.fromkeys(t['path'] for l in g['layers'] for t in l['textureSlots'] if t.get('path')))
  evidence=[f"captures/models/{o['modelId']}/{cp[k]}" for k in ['file','sideFile','contextFile'] if cp.get(k)]
  out.append({**o,'triangles':p['triangles'],'vertices':p['vertices'],'distinctPositions':p['distinctPositions'],'sourceTexturePaths':textures,'posedBounds':p['posedBounds'],'boneNamesSupportingLocation':[b['name'] for b in p['bones']],'visibleAtSample':p['visible'],'sample':m['sample'],'uvBounds':p['uv']['bounds'],'uvTriangles':p['uv']['triangles'],'visualEvidence':evidence,'captureVersion':cap.get('researchCaptureVersion'),'animatedGeosetColorsConvertedToRGB':cap.get('animatedGeosetColorsConvertedToRGB',False)})
 for mid,m in models.items():
  expected={x['id'] for x in m['parts']};actual={x['componentId'] for x in out if x['modelId']==mid};assert expected==actual,(mid,expected-actual,actual-expected)
 assert len(out)==len({x['componentId'] for x in out})
 for dest in [D/'annotations/lpw-vampire-vision.json',DOC/'data/lpw-vampire-vision.json']:dest.write_text(json.dumps(out,indent=2),encoding='utf8')
 print(json.dumps({'models':len(models),'annotations':len(out),'perModel':{m:sum(x['modelId']==m for x in out) for m in models}}))
if __name__=='__main__':emit()
